#include <vector>

using namespace std;

class Solution {
public:
    vector<int> processQueries(vector<int>& queries, int m) {
        vector<int> perm(m);
        for (int i = 0; i < m; ++i) perm[i] = i + 1;
        vector<int> res;
        for (int q : queries) {
            for (int i = 0; i < m; ++i) {
                if (perm[i] == q) {
                    res.push_back(i);
                    perm.erase(perm.begin() + i);
                    perm.insert(perm.begin(), q);
                    break;
                }
            }
        }
        return res;
    }
};
